eld Gen2","--  silent aim + esp + enabled-features HUD","-- =====================================================================","","-- SERVICES -----------------------------------------------------------","local Players           = game:GetService(\"Players\")","local RunService        = game:GetService(\"RunService\")","local UserInputService  = game:GetService(\"UserInputService\")","local Workspace         = game:GetService(\"Workspace\")","local ReplicatedStorage = game:GetService(\"ReplicatedStorage\")","local CoreGui           = game:GetService(\"CoreGui\")","","local Camera      = Workspace.CurrentCamera","local LocalPlayer = Players.LocalPlayer","","-- RAYFIELD -----------------------------------------------------------","local Rayfield = loadstring(game:HttpGet(\"https://sirius.menu/gen2\"))()","","local window = Rayfield:CreateWindow({","    name = \"Auth.WTF\",","    subtitle = \"Made by itzrockx\",","    sidebarLayout = true,","})","","-- FEATURE STATE ------------------------------------------------------","local Features = {","    SilentAim    = false,","    ESP          = false,","    TeamCheck    = true,","    ShowSkeleton = true,","    ShowTracer   = true,","    ShowHeadDot  = true,","    ShowInfo     = true,","    FOV          = 150,","    MaxDistance  = 1000,","    AimOffset    = 0,","}","","local SilentAimKey = nil","","-- SHARED OBJECTS -----------------------------------------------------","local espObjects = {}","","local FOVCircle = Drawing.new(\"Circle\")","FOVCircle.Thickness    = 1.5","FOVCircle.NumSides     = 64","FOVCircle.Radius       = Features.FOV","FOVCircle.Filled       = false","FOVCircle.Visible      = false","FOVCircle.Color        = Color3.fromRGB(0, 0, 0)","FOVCircle.Transparency = 0.6","","-- =====================================================================","--  ENABLED-FEATURES HUD (bottom-right)","-- =====================================================================","local hudGui = Instance.new(\"ScreenGui\")","hudGui.Name = \"AuthWTF_HUD\"","hudGui.ResetOnSpawn = false","hudGui.IgnoreGuiInset = true","hudGui.DisplayOrder = 999","hudGui.Parent = CoreGui","","local hudFrame = Instance.new(\"Frame\")","hudFrame.AnchorPoint = Vector2.new(1, 1)","hudFrame.Position = UDim2.new(1, -14, 1, -14)","hudFrame.Size = UDim2.new(0, 220, 0, 0)","hudFrame.AutomaticSize = Enum.AutomaticSize.Y","hudFrame.BackgroundColor3 = Color3.fromRGB(12, 12, 16)","hudFrame.BackgroundTransparency = 0.25","hudFrame.BorderSizePixel = 0","hudFrame.Parent = hudGui","","local hudCorner = Instance.new(\"UICorner\", hudFrame)","hudCorner.CornerRadius = UDim.new(0, 6)","","local hudPadding = Instance.new(\"UIPadding\", hudFrame)","hudPadding.PaddingTop    = UDim.new(0, 8)","hudPadding.PaddingBottom = UDim.new(0, 8)","hudPadding.PaddingLeft   = UDim.new(0, 10)","hudPadding.PaddingRight  = UDim.new(0, 10)","","local hudTitle = Instance.new(\"TextLabel\")","hudTitle.Size = UDim2.new(1, 0, 0, 16)","hudTitle.BackgroundTransparency = 1","hudTitle.Text = \"AUTH.WTF  ·  ENABLED\"","hudTitle.Font = Enum.Font.GothamBold","hudTitle.TextSize = 11","hudTitle.TextColor3 = Color3.fromRGB(120, 200, 255)","hudTitle.TextXAlignment = Enum.TextXAlignment.Left","hudTitle.Parent = hudFrame","","local hudList = Instance.new(\"Frame\")","hudList.Size = UDim2.new(1, 0, 0, 0)","hudList.AutomaticSize = Enum.AutomaticSize.Y","hudList.BackgroundTransparency = 1","hudList.Position = UDim2.new(0, 0, 0, 20)","hudList.Parent = hudFrame","","local hudLayout = Instance.new(\"UIListLayout\", hudList)","hudLayout.Padding = UDim.new(0, 2)","hudLayout.SortOrder = Enum.SortOrder.LayoutOrder","","local hudRows = {}","","local function makeHudRow(featureKey, label, order)","    local row = Instance.new(\"TextLabel\")","    row.Size = UDim2.new(1, 0, 0, 14)","    row.BackgroundTransparency = 1","    row.Text = \"• \" .. label","    row.Font = Enum.Font.Gotham","    row.TextSize = 11","    row.TextColor3 = Color3.fromRGB(230, 230, 230)","    row.TextXAlignment = Enum.TextXAlignment.Left","    row.Visible = false","    row.LayoutOrder = order","    row.Parent = hudList","    hudRows[featureKey] = row","end","","makeHudRow(\"SilentAim\",    \"Silent Aim\",   1)","makeHudRow(\"ESP\",          \"ESP\",          2)","makeHudRow(\"ShowSkeleton\", \"Skeleton\",     3)","makeHudRow(\"ShowTracer\",   \"Tracers\",      4)","makeHudRow(\"ShowHeadDot\",  \"Head Dot\",     5)","makeHudRow(\"ShowInfo\",     \"Info Text\",    6)","makeHudRow(\"TeamCheck\",    \"Team Check\",   7)","","local function refreshHud()","    for key, row in pairs(hudRows) do","        if Features[key] then","            row.Visible = true","        else","            row.Visible = false","        end","    end","end","","RunService.RenderStepped:Connect(refreshHud)","","-- =====================================================================","--  MAIN TAB","-- =====================================================================","local mainTab = window:CreateTab({ name = \"Main\", icon = 93364949241311 })","","mainTab:CreateSection({ name = \"Silent Aim\" })","","mainTab:CreateToggle({","    name = \"Silent Aim\",","    currentValue = false,","    flag = \"SilentAimToggle\",","    callback = function(value)","        Features.SilentAim = value","        FOVCircle.Visible = value","    end,","})","","mainTab:CreateButton({","    name = \"Set Silent Aim Keybind\",","    callback = function()","        task.spawn(function()","            pcall(function()","                Rayfield:Notify({","                    Title = \"Auth.WTF\",","                    Content = \"Press any keyboard key or right-click to bind. 8s.\",","                    Duration = 3,","                })","            end)","","            local listening = true","            local captured = nil","","            local conn","            conn = UserInputService.InputBegan:Connect(function(input, processed)","                if not listening then return end","                if input.UserInputType == Enum.UserInputType.MouseButton2","                    or input.UserInputType == Enum.UserInputType.Keyboard then","                    captured = input","                    listening = false","                end","            end)","","            local startTime = tick()","            while listening and tick() - startTime \u003c 8 do","                task.wait(0.1)","            end","","            conn:Disconnect()","","            if captured then","                if captured.UserInputType == Enum.UserInputType.Keyboard then","                    SilentAimKey = captured.KeyCode","                else","                    SilentAimKey = Enum.UserInputType.MouseButton2","                end","","                pcall(function()","                    Rayfield:Notify({","                        Title = \"Auth.WTF\",","                        Content = \"Silent Aim key set.\",","                        Duration = 3,","                    })","                end)","            else","                pcall(function()","                    Rayfield:Notify({","                        Title = \"Auth.WTF\",","                        Content = \"No key captured.\",","                        Duration = 3,","                    })","                end)","            end","        end)","    end,","})","","mainTab:CreateToggle({","    name = \"Team Check\",","    currentValue = true,","    flag = \"TeamCheckToggle\",","    callback = function(value)","        Features.TeamCheck = value","    end,","})","","mainTab:CreateSlider({","    name = \"FOV\",","    range = { 50, 500 },","    increment = 10,","    suffix = \"px\",","    currentValue = 150,","    flag = \"FOVSlider\",","    callback = function(value)","        Features.FOV = value","        FOVCircle.Radius = value","    end,","})","","mainTab:CreateSlider({","    name = \"Aim Offset (vertical)\",","    range = { -10, 10 },","    increment = 1,","    suffix = \"studs\",","    currentValue = 0,","    flag = \"AimOffsetSlider\",","    callback = function(value)","        Features.AimOffset = value","    end,","})","","-- =====================================================================","--  ESP TAB","-- =====================================================================","local espTab = window:CreateTab({ name = \"ESP\", icon = 6031263794 })","","espTab:CreateSection({ name = \"ESP\" })","","espTab:CreateToggle({","    name = \"Enable ESP\",","    currentValue = false,","    flag = \"ESPToggle\",","    callback = function(value)","        Features.ESP = value","        if not value then","            for _, data in pairs(espObjects) do","                for _, obj in pairs(data.objects) do","                    if obj then obj.Visible = false end","                end","            end","        end","    end,","})","","local skeletonToggle = espTab:CreateToggle({","    name = \"Skeleton\",","    currentValue = true,","    flag = \"ShowSkeletonToggle\",","    callback = function(value) Features.ShowSkeleton = value end,","})","","local tracerToggle = espTab:CreateToggle({","    name = \"Tracers\",","    currentValue = true,","    flag = \"ShowTracerToggle\",","    callback = function(value) Features.ShowTracer = value end,","})","","local headDotToggle = espTab:CreateToggle({","    name = \"Head Dot\",","    currentValue = true,","    flag = \"ShowHeadDotToggle\",","    callback = function(value) Features.ShowHeadDot = value end,","})","","local infoToggle = espTab:CreateToggle({","    name = \"Info Text\",","    currentValue = true,","    flag = \"ShowInfoToggle\",","    callback = function(value) Features.ShowInfo = value end,","})","","task.defer(function()","    task.wait(0.15)","    pcall(function() skeletonToggle:Set(true) end)","    pcall(function() tracerToggle:Set(true) end)","    pcall(function() headDotToggle:Set(true) end)","    pcall(function() infoToggle:Set(true) end)","    Features.ShowSkeleton = true","    Features.ShowTracer   = true","    Features.ShowHeadDot  = true","    Features.ShowInfo     = true","end)","","espTab:CreateSlider({","    name = \"Max Distance\",","    range = { 100, 2000 },","    increment = 50,","    suffix = \"studs\",","    currentValue = 1000,","    flag = \"MaxDistanceSlider\",","    callback = function(value)","        Features.MaxDistance = value","    end,","})","","-- =====================================================================","--  SILENT AIM — TARGETING","-- =====================================================================","local function isEnemy(player)","    if not Features.TeamCheck then return true end","    if not player.Team or not LocalPlayer.Team then return true end","    return player.Team ~= LocalPlayer.Team","end","","local targetLock = nil","local lastTargetTime = 0","local targetLockTime = 0.8","local lastTargetPosition = nil","local targetVelocity = Vector3.new(0, 0, 0)","","local function getBestTarget()","    if not LocalPlayer.Character","        or not LocalPlayer.Character:FindFirstChild(\"HumanoidRootPart\") then","        return nil","    end","","    local bestTarget = nil","    local bestScore = math.huge","    local screenCenter = Vector2.new(Camera.ViewportSize.X / 2,","                                      Camera.ViewportSize.Y / 2)","    local localPos = LocalPlayer.Character.HumanoidRootPart.Position","","    for _, player in pairs(Players:GetPlayers()) do","        if player ~= LocalPlayer and player.Character and isEnemy(player) then","            local head    = player.Character:FindFirstChild(\"Head\")","            local hrp     = player.Character:FindFirstChild(\"HumanoidRootPart\")","            local humanoid= player.Character:FindFirstChild(\"Humanoid\")","","            if head and hrp and humanoid and humanoid.Health \u003e 0 then","                local distance = (hrp.Position - localPos).Magnitude","","                if distance \u003c= Features.MaxDistance then","                    local aimPosition = head.Position","                                        + Vector3.new(0, Features.AimOffset, 0)","                    local screenPos, onScreen =","                        Camera:WorldToViewportPoint(aimPosition)","","                    if onScreen then","                        local screenPos2D = Vector2.new(screenPos.X, screenPos.Y)","                        local distFromCenter =","                            (screenPos2D - screenCenter).Magnitude","","                        local effectiveFOV = Features.FOV","                        if distance \u003c 30 then","                            effectiveFOV = effectiveFOV * 2.0","                        elseif distance \u003c 100 then","                            effectiveFOV = effectiveFOV * 1.3","                        end","","                        if distFromCenter \u003c= effectiveFOV then","                            local distanceScore =","                                distance \u003c 50 and distance * 3 or distance * 0.5","                            local centerScore =","                                distFromCenter * (distance \u003c 30 and 0.3 or 1.0)","                            local score = centerScore + distanceScore","","                            if score \u003c bestScore then","                                bestScore = score","                                bestTarget = {","                                    Head             = head,","                                    HumanoidRootPart = hrp,","                                    Position         = aimPosition,","                                    Distance         = distance,","                                    Player           = player,","                                }","                            end","                        end","                    end","                end","            end","        end","    end","","    return bestTarget","end","","local function getTargetWithLock()","    local currentTime = tick()","","    if targetLock and targetLock.Head and targetLock.Head.Parent then","        local player = targetLock.Player","        if player and isEnemy(player) then","            local hrp      = targetLock.HumanoidRootPart","            local humanoid = targetLock.Head.Parent:FindFirstChildOfClass(\"Humanoid\")","","            if hrp and humanoid and humanoid.Health \u003e 0 then","                local distance = (hrp.Position","                    - LocalPlayer.Character.HumanoidRootPart.Position).Magnitude","                local aimPosition = targetLock.Head.Position","                                    + Vector3.new(0, Features.AimOffset, 0)","                local _, onScreen =","                    Camera:WorldToViewportPoint(aimPosition)","","                if onScreen","                    and distance \u003c= Features.MaxDistance","                    and (currentTime - lastTargetTime) \u003c targetLockTime then","                    if lastTargetPosition then","                        targetVelocity =","                            (aimPosition - lastTargetPosition) * 0.5","                    end","                    lastTargetPosition = aimPosition","                    lastTargetTime     = currentTime","","                    targetLock.Position =","                        aimPosition + (targetVelocity * 0.1)","                    targetLock.Distance = distance","                    return targetLock","                end","            end","        end","    end","","    local newTarget = getBestTarget()","    if newTarget then","        targetLock         = newTarget","        lastTargetTime     = currentTime","        lastTargetPosition = newTarget.Position","        targetVelocity     = Vector3.new(0, 0, 0)","    else","        targetLock         = nil","        lastTargetPosition = nil","    end","","    return targetLock","end","","-- =====================================================================","--  RENDER LOOP","-- =====================================================================","RunService.RenderStepped:Connect(function()","    FOVCircle.Position = Vector2.new(Camera.ViewportSize.X / 2,","                                     Camera.ViewportSize.Y / 2)","    FOVCircle.Radius   = Features.FOV","    FOVCircle.Visible  = Features.SilentAim","","    if Features.SilentAim and LocalPlayer.Character then","        local target = getTargetWithLock()","","        if target and target.Head then","            local targetPos      = target.Position","            local currentCFrame  = Camera.CFrame","","            local smoothness = target.Distance \u003c 30 and 0.35 or 0.15","            if target.Distance \u003c 10 then","                smoothness = 0.5","            end","","            local targetDirection =","                (targetPos - currentCFrame.Position).Unit","            local targetCFrame = CFrame.new(","                currentCFrame.Position,","                currentCFrame.Position + targetDirection","            )","","            Camera.CFrame = currentCFrame:Lerp(targetCFrame, smoothness)","        end","    end","end)","","-- =====================================================================","--  KEYBIND HANDLER","-- =====================================================================","UserInputService.InputBegan:Connect(function(input, processed)","    if SilentAimKey and typeof(SilentAimKey) == \"EnumItem\" then","        local matches = false","        if SilentAimKey.EnumType == Enum.KeyCode then","            matches = (input.KeyCode == SilentAimKey)","        elseif SilentAimKey.EnumType == Enum.UserInputType then","            matches = (input.UserInputType == SilentAimKey)","        end","","        if matches then","            Features.SilentAim = not Features.SilentAim","            FOVCircle.Visible = Features.SilentAim","            pcall(function()","                Rayfield:Notify({","                    Title = \"Auth.WTF\",","                    Content = \"Silent Aim: \" .. (Features.SilentAim and \"ON\" or \"OFF\"),","                    Duration = 2,","                })","            end)","        end","    end","","    if input.UserInputType == Enum.UserInputType.MouseButton1","        and Features.SilentAim","        and not processed then","        local target = getTargetWithLock()","        if target and target.Head then","            Camera.CFrame = CFrame.new(Camera.CFrame.Position, target.Position)","","            if ReplicatedStorage:FindFirstChild(\"Remotes\") then","                for _, remote in pairs(ReplicatedStorage.Remotes:GetChildren()) do","                    if remote:IsA(\"RemoteEvent\") then","                        local name = remote.Name:lower()","                        if name:match(\"attack\")","                            or name:match(\"hit\")","                            or name:match(\"damage\")","                            or name:match(\"combat\") then","                            pcall(function()","                                remote:FireServer(target.Position)","                            end)","                        end","                    end","                end","            end","","            if target.Distance \u003c 15 then","                pcall(function()","                    local tool =","                        LocalPlayer.Character:FindFirstChildOfClass(\"Tool\")","                    if tool then tool:Activate() end","                end)","            end","        end","    end","end)","","-- =====================================================================","--  ESP RENDERING","-- =====================================================================","local bodyConnections = {","    {\"Head\", \"UpperTorso\"}, {\"UpperTorso\", \"LowerTorso\"},","    {\"UpperTorso\", \"LeftUpperArm\"},","    {\"LeftUpperArm\", \"LeftLowerArm\"},","    {\"LeftLowerArm\", \"LeftHand\"},","    {\"UpperTorso\", \"RightUpperArm\"},","    {\"RightUpperArm\", \"RightLowerArm\"},","    {\"RightLowerArm\", \"RightHand\"},","    {\"LowerTorso\", \"LeftUpperLeg\"},","    {\"LeftUpperLeg\", \"LeftLowerLeg\"},","    {\"LeftLowerLeg\", \"LeftFoot\"},","    {\"LowerTorso\", \"RightUpperLeg\"},","    {\"RightUpperLeg\", \"RightLowerLeg\"},","    {\"RightLowerLeg\", \"RightFoot\"},","}","","local function createESP(player)","    if player == LocalPlayer then return end","","    local objects = {}","","    for i = 1, 14 do","        local line = Drawing.new(\"Line\")","        line.Thickness     = 1.5","        line.Transparency  = 0.8","        line.Visible       = false","        table.insert(objects, line)","    end","","    local headCircle = Drawing.new(\"Circle\")","    headCircle.Thickness = 2","    headCircle.NumSides  = 12","    headCircle.Radius    = 4","    headCircle.Filled    = true","    headCircle.Visible   = false","    table.insert(objects, headCircle)","","    local tracer = Drawing.new(\"Line\")","    tracer.Thickness    = 1","    tracer.Transparency = 0.5","    tracer.Visible      = false","    table.insert(objects, tracer)","","    local infoText = Drawing.new(\"Text\")","    infoText.Size         = 13","    infoText.Center       = true","    infoText.Outline      = true","    infoText.OutlineColor = Color3.fromRGB(0, 0, 0)","    infoText.Visible      = false","    table.insert(objects, infoText)","","    espObjects[player] = { objects = objects, player = player }","","    player.AncestryChanged:Connect(function()","        if not player:IsDescendantOf(game) then","            for _, obj in pairs(objects) do obj:Remove() end","            espObjects[player] = nil","        end","    end)","end","","RunService.RenderStepped:Connect(function()","    for player, data in pairs(espObjects) do","        local objects = data.objects","        local char    = player.Character","","        if Features.ESP and char and isEnemy(player) then","            local humanoid = char:FindFirstChild(\"Humanoid\")","            local hrp      = char:FindFirstChild(\"HumanoidRootPart\")","            local head     = char:FindFirstChild(\"Head\")","","            if humanoid and hrp and head then","                local distance =","                    (hrp.Position - Camera.CFrame.Position).Magnitude","","                if distance \u003c= Features.MaxDistance then","                    local headPos, headOnScreen =","                        Camera:WorldToViewportPoint(head.Position)","                    local rootPos, rootOnScreen =","                        Camera:WorldToViewportPoint(hrp.Position)","","                    if headOnScreen or rootOnScreen then","                        local color = Color3.fromRGB(255, 50, 50)","","                        if Features.ShowSkeleton then","                            for i, connection in pairs(bodyConnections) do","                                if i \u003c= #objects - 3 then","                                    local part1 = char:FindFirstChild(connection[1])","                                    local part2 = char:FindFirstChild(connection[2])","                                    if part1 and part2 then","                                        local pos1, on1 =","                                            Camera:WorldToViewportPoint(part1.Position)","                                        local pos2, on2 =","                                            Camera:WorldToViewportPoint(part2.Position)","                                        local line = objects[i]","                                        if on1 and on2 then","                                            line.From    =","                                                Vector2.new(pos1.X, pos1.Y)","                                            line.To      =","                                                Vector2.new(pos2.X, pos2.Y)","                                            line.Color   = color","                                            line.Visible = true","                                        else","                                            line.Visible = false","                                        end","                                    end","                                end","                            end","                        end","","                        if Features.ShowHeadDot then","                            local circle = objects[#objects - 2]","                            circle.Position = Vector2.new(headPos.X, headPos.Y)","                            circle.Color    = color","                            circle.Radius   =","                                math.clamp(800 / distance, 3, 8)","                            circle.Visible  = true","                        end","","                        if Features.ShowTracer then","                            local tracer = objects[#objects - 1]","                            tracer.From = Vector2.new(","                                Camera.ViewportSize.X / 2,","                                Camera.ViewportSize.Y","                            )","                            tracer.To    = Vector2.new(rootPos.X, rootPos.Y)","                            tracer.Color = color","                            tracer.Visible = true","                        end","","                        if Features.ShowInfo then","                            local text = objects[#objects]","                            text.Position =","                                Vector2.new(headPos.X, headPos.Y - 40)","                            text.Text = string.format(","                                \"%s\\n[%dHP] [%dm]\",","                                player.Name,","                                math.floor(humanoid.Health),","                                math.floor(distance)","                            )","                            text.Color   = Color3.fromRGB(255, 255, 255)","                            text.Visible = true","                        end","       